# frozen_string_literal: true

require 'adwaita'
require 'fileutils'

require_relative 'logging'

module Errands
  # Icons carries the application's symbolic icons.
  #
  # Ported from upstream's data/icons/hicolor/symbolic/apps/*.svg, which meson
  # compiles into errands.gresource and the application registers as a resource
  # base path. This port has no gresource build step, so the same SVG markup is
  # embedded here and written into an icon theme directory under the user's
  # cache directory, which is then added to the icon theme's search path. Every
  # `icon_name` in this port resolves through it.
  #
  module Icons
    THEME_DIR_NAME = 'hicolor'

    INDEX_THEME = <<~INDEX
      [Icon Theme]
      Name=Errands
      Comment=Errands symbolic icons
      Directories=scalable/apps

      [scalable/apps]
      Size=16
      MinSize=16
      MaxSize=512
      Context=Applications
      Type=Scalable
    INDEX

