    class << self
      # Writes the icons out (once per run) and puts their theme on the icon
      # theme's search path.
      def install
        Log.debug('Icons: Install symbolic icons')
        FileUtils.mkdir_p(apps_dir)
        File.write(File.join(theme_dir, 'index.theme'), INDEX_THEME)
        SVG.each { |name, markup| File.write(File.join(apps_dir, "#{name}.svg"), "#{markup}\n") }
        Gtk::IconTheme.get_for_display(Gdk::Display.default).add_search_path(search_path)
      end

      def search_path = @search_path ||= File.join(GLib.user_cache_dir, 'errands', 'icons')

      private

        def theme_dir = File.join(search_path, THEME_DIR_NAME)

        def apps_dir = File.join(theme_dir, 'scalable', 'apps')
    end
  end
end
